    b_normalized = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_normalized:
        return []

    # Merge overlapping/touching intervals in b for efficient subtraction
    b_merged = []
    for start, end in b_normalized:
        if b_merged and start <= b_merged[-1][1]:
            # Overlapping or touching: merge
            b_merged[-1] = [b_merged[-1][0], max(b_merged[-1][1], end)]
        else:
            b_merged.append([start, end])

    result = []

    for a_start, a_end in a_normalized:
        current_start = a_start

        for b_start, b_end in b_merged:
            if b_end <= current_start:
                # b interval is completely before current position
                continue
            if b_start >= a_end:
                # b interval is completely after current interval
                break

            # b interval overlaps with [current_start, a_end)
            if current_start < b_start:
                # Add the part before b_start
                result.append([current_start, b_start])

            # Move current_start past b_end
            current_start = max(current_start, b_end)

        # Add remaining part of a interval
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge adjacent intervals in result
    if not result:
        return []

    merged_result = [result[0]]
